#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_progress;
uniform float amzp_sliceCount;
uniform float amzp_sliceRadius;
uniform float amzp_explosionSpeed;
uniform float amzp_glowIntensity;
layout(color) uniform half4 amzp_glowColor;
uniform float amzp_flashEnabled;
uniform float amzp_seed;
    float hash(float n) {
        return fract(sin(n) * 43758.5453123);
    }
    float2x2 rot(float a) {
        float s = sin(a), c = cos(a);
        return float2x2(c, -s, s, c);
    }
    struct ShardInfo {
        float id;
        float2 moveDir;
        float distToCut;
    };
    ShardInfo getShardInfo(float2 p, float numCuts, float cutRadius) {
        float id = 0.0;
        float2 moveAcc = float2(0.0);
        float minDist = 100.0;
        int NUM_CUTS = int(numCuts);
        for(int i = 0; i < 30; i++) {
            if(i >= NUM_CUTS) break;
            float fi = float(i);
            float h1 = hash(fi + amzp_seed);
            float h2 = hash(fi + amzp_seed * 5.0 + 99.0);
            float angle = h1 * 3.14159265359 * 2.0;
            float2 n = float2(cos(angle), sin(angle));
            float off = (h2 - 0.5) * cutRadius;
            float d = dot(p, n) - off;
            minDist = min(minDist, abs(d));
            float side = sign(d);
            if(side > 0.0) {
                id += pow(1.5, fi);
            }
            moveAcc += n * side;
        }
        float2 randomDir = float2(hash(id) - 0.5, hash(id + 1.0) - 0.5);
        moveAcc += randomDir * 1.5;
        return ShardInfo(id, normalize(moveAcc), minDist);
    }
    float drawSwipe(float2 p, float2 n, float off, float t, float hashSeed) {
        float2 tangent = float2(-n.y, n.x);
        float posAlongLine = dot(p, tangent);
        float dir = step(0.5, hash(hashSeed)) * 2.0 - 1.0;
        float swipe = (t * 12.0 - 6.0) * dir;
        return smoothstep(-0.2, 0.2, (swipe - posAlongLine) * dir);
    }
    void amzRender() {
        float2 texSize = getTexSize((screen.zw/1.0));
        float2 uv = amzScreenNorm();
        float2 p = (amzScreenNorm() - 0.5) * float2(texSize.x / texSize.y, 1.0);
        float t = amzp_progress * 4.0;
        float slashEnd = 1.2;
        float explodeStart = 1.4;
        if (amzp_progress <= 0.001) {
            amzOutput = amzTexture(0, uv);
            return;
        }
        float force = 0.0;
        if(t > explodeStart) {
            float et = t - explodeStart;
            force = et * et * amzp_explosionSpeed + et * 0.2;
        }
        int NUM_CUTS = int(amzp_sliceCount);
        ShardInfo destInfo = getShardInfo(p, amzp_sliceCount, amzp_sliceRadius);
        float zScale = 1.0;
        if(force > 0.0) {
             zScale = 1.0 + (hash(destInfo.id) - 0.5) * force;
             zScale = max(0.1, zScale);
        }
        float2 offset = destInfo.moveDir * force;
        float2 srcP = (p - offset) / zScale;
        ShardInfo srcInfo = getShardInfo(srcP, amzp_sliceCount, amzp_sliceRadius);
        bool isSameShard = abs(destInfo.id - srcInfo.id) < 0.1;
        float3 col = float3(0.0);
        float alpha = 0.0;
        if (isSameShard) {
            float2 srcUV = srcP / float2(texSize.x / texSize.y, 1.0) + 0.5;
            if(srcUV.x >= 0.0 && srcUV.x <= 1.0 && srcUV.y >= 0.0 && srcUV.y <= 1.0) {
                float4 texCol = amzTexture(0, srcUV);
                col = texCol.rgb;
                alpha = texCol.a;
                if(force > 0.0) {
                    float dim = 1.0 / (1.0 + force * 0.5);
                    float glint = sin(force * 5.0 + hash(destInfo.id)*10.0) * 0.5 + 0.5;
                    col *= dim * (0.8 + 0.4*glint);
                }
            }
        }
        if (t < explodeStart + 0.5) {
            float accumulatedGlow = 0.0;
            for(int i = 0; i < 30; i++) {
                if(i >= NUM_CUTS) break;
                float fi = float(i);
                float h1 = hash(fi + amzp_seed);
                float h2 = hash(fi + amzp_seed * 5.0 + 99.0);
                float angle = h1 * 3.14159265359 * 2.0;
                float2 n = float2(cos(angle), sin(angle));
                float off = (h2 - 0.5) * amzp_sliceRadius;
                float d = abs(dot(p, n) - off);
                float myStart = (fi / float(NUM_CUTS)) * slashEnd;
                if(t > myStart) {
                    float locT = t - myStart;
                    float line = 0.0015 / (d + 0.0001);
                    float swipe = drawSwipe(p, n, off, locT, h1);
                    float fade = exp(-locT * 4.0);
                    accumulatedGlow += line * swipe * fade * 2.0;
                }
            }
            col += amzp_glowColor.rgb * accumulatedGlow * amzp_glowIntensity;
            alpha = max(alpha, accumulatedGlow * amzp_glowIntensity);
        }
        float flash = smoothstep(explodeStart, explodeStart + 0.05, t) *
                      (1.0 - smoothstep(explodeStart + 0.05, explodeStart + 0.4, t));
        if ((amzp_flashEnabled>0.5)) {
            col += float3(1.0) * flash;
            alpha = max(alpha, flash);
        }
        amzOutput = float4(col, alpha);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
